	const links = await database.query.factCases.findMany({
		where: (factCases, { eq }) => eq(factCases.caseId, caseId),
		with: {
			fact: {
				with: {
					apartmentLinks: true,
					caseLinks: true,
					houseLinks: true,
					source: true,
				},
			},
		},
	});

	return links.map((link) =>
		sanitizeToolPayload({
			id: link.fact.id,
			propertyId: link.fact.propertyId,
			category: link.fact.category,
			key: link.fact.key,
			value: link.fact.value,
